  @protected
  void sse_encode_sync_event(SyncEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case SyncEvent_Syncing(folderId: final folderId):
        sse_encode_i_32(0, serializer);
        sse_encode_String(folderId, serializer);
      case SyncEvent_Idle():
        sse_encode_i_32(1, serializer);
      case SyncEvent_Error(message: final message):
        sse_encode_i_32(2, serializer);
        sse_encode_String(message, serializer);
      case SyncEvent_PairRequested(name: final name, id: final id):
        sse_encode_i_32(3, serializer);
        sse_encode_String(name, serializer);
        sse_encode_String(id, serializer);
      case SyncEvent_FolderPairRequested(
          name: final name,
          id: final id,
