        sse_encode_i_32(4, serializer);
        sse_encode_String(name, serializer);
        sse_encode_String(id, serializer);
        sse_encode_String(folder, serializer);
      case SyncEvent_DevicePaired(name: final name, id: final id):
        sse_encode_i_32(5, serializer);
        sse_encode_String(name, serializer);
        sse_encode_String(id, serializer);
      case SyncEvent_FilePulled(path: final path, device: final device):
        sse_encode_i_32(6, serializer);
        sse_encode_String(path, serializer);
        sse_encode_String(device, serializer);
      case SyncEvent_FilePushed(path: final path, device: final device):
        sse_encode_i_32(7, serializer);
        sse_encode_String(path, serializer);
        sse_encode_String(device, serializer);
      case SyncEvent_Conflict(
          path: final path,
