          loser: final loser
        ):
        sse_encode_i_32(8, serializer);
        sse_encode_String(path, serializer);
        sse_encode_String(winner, serializer);
        sse_encode_String(loser, serializer);
      case SyncEvent_Progress(
          folderId: final folderId,
          stage: final stage,
          filesDone: final filesDone,
          filesTotal: final filesTotal,
          bytesDone: final bytesDone,
          bytesTotal: final bytesTotal
        ):
        sse_encode_i_32(9, serializer);
        sse_encode_String(folderId, serializer);
        sse_encode_String(stage, serializer);
        sse_encode_u_64(filesDone, serializer);
        sse_encode_u_64(filesTotal, serializer);
        sse_encode_u_64(bytesDone, serializer);
        sse_encode_u_64(bytesTotal, serializer);
